def check_points(coords):
    points = [Point(x, y) for x, y in coords]
    pairs = [[p.x, p.y] for p in distinct(points)]
    try:
        value_equality = Point(0, 0) == Point(0, 0) and len({Point(0, 0), Point(0, 0)}) == 1
    except TypeError:
        value_equality = False
    return [pairs, value_equality]

