public static class PointCheck
{
    public static object[] Check(int[][] coords)
    {
        var points = coords.Select(c => new Point(c[0], c[1])).ToList();
        var pairs = Solution.Distinct(points).Select(p => new[] { p.X, p.Y }).ToList();
        var valueEquality = new Point(0, 0).Equals(new Point(0, 0))
            && new HashSet<Point> { new Point(0, 0), new Point(0, 0) }.Count == 1;
        return [pairs, valueEquality];
    }
}

